/bin/bash -lc "cat > src/semantic_version_precedence.ts <<'EOF'
function parts(value: string): { core: string[]; prerelease: string[] } {
  if ("'!/''^(0|[1-9]'"\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?"'$(?!['"\\s\\S])/.test(value)) {
    throw new Error(\"invalid version\");
  }
  const main = value.split(\"+\")[0];
  const dash = main.indexOf(\"-\");
  const prerelease = dash < 0 ? [] : main.slice(dash + 1).split(\".\");
  if (prerelease.some(p => /"'^'"\\d+"'$/.test(p) && p.length > 1 && p.startsWith("0"))) {
    throw new Error("leading zero");
  }
  return { core: (dash < 0 ? main : main.slice(0, dash)).split("."), prerelease };
}

// Canonical decimal strings can be compared exactly without numeric conversion.
function compareNumeric(left: string, right: string): number {
  if (left.length !== right.length) return left.length < right.length ? -1 : 1;
  return left === right ? 0 : left < right ? -1 : 1;
}

export function compareVersions(left: string, right: string): number {
  const a = parts(left);
  const b = parts(right);
  for (let i = 0; i < 3; i++) {
    const order = compareNumeric(a.core[i], b.core[i]);
    if (order !== 0) return order;
  }
  if (a.prerelease.length === 0 || b.prerelease.length === 0) {
    return a.prerelease.length === b.prerelease.length ? 0 : a.prerelease.length === 0 ? 1 : -1;
  }
  for (let i = 0; i < Math.min(a.prerelease.length, b.prerelease.length); i++) {
    const x = a.prerelease[i];
    const y = b.prerelease[i];
    if (x === y) continue;
    const xNumeric = /''^'"\\d+"'$/.test(x);
    const yNumeric = /''^'"\\d+"'$/.test(y);
    if (xNumeric && yNumeric) return compareNumeric(x, y);
    if (xNumeric !== yNumeric) return xNumeric ? -1 : 1;
    return x < y ? -1 : 1;
  }
  return compareNumeric(String(a.prerelease.length), String(b.prerelease.length));
}
EOF
cat > tests/semantic_version_precedence.test.mjs <<'"'EOF'
import test from \"node:test\";
import assert from \"node:assert/strict\";
import { compareVersions as domain } from \"../src/semantic_version_precedence.ts\";
import { compareVersions as api } from \"../src/api.ts\";

for (const [name, compare] of Object.entries({ domain, api })) {
  test("'`${name}: semantic version precedence`, () => {
    const pairs = [
      ["2.0.0", "10.0.0"],
      ["1.2.0", "1.10.0"],
      ["1.0.2", "1.0.10"],
      ["1.0.0-alpha", "1.0.0-alpha.1"],
      ["1.0.0-alpha.1", "1.0.0-alpha.beta"],
      ["1.0.0-alpha.beta", "1.0.0-beta"],
      ["1.0.0-beta", "1.0.0-beta.2"],
      ["1.0.0-beta.2", "1.0.0-beta.11"],
      ["1.0.0-beta.11", "1.0.0-rc.1"],
      ["1.0.0-rc.1", "1.0.0"],
      ["1.0.0-9", "1.0.0--"],
      ["1.0.0-A", "1.0.0-a"],
      ["9007199254740992.0.0", "9007199254740993.0.0"],
      ["1.0.0-9007199254740992", "1.0.0-9007199254740993"],
      [`1.0.0-${"9".repeat(400)}`, `1.0.0-1${"0".repeat(400)}`],
    ];
    for (const [left, right] of pairs) {
      assert.equal(compare(left, right), -1, `${left} < ${right}`);
      assert.equal(compare(right, left), 1, `${right} > ${left}`);
      assert.equal(compare(left, left), 0);
    }
    assert.equal(compare("1.2.3+001.a-b", "1.2.3+other"), 0);
    assert.equal(compare("1.2.3-alpha+001", "1.2.3-alpha"), 0);
  });

  test(`${name}: rejects invalid semantic versions in either argument`, () => {
    for (const invalid of [
      "", "1", "1.2", "v1.2.3", "01.2.3", "1.02.3", "1.2.03",
      "-1.2.3", "1.2.3-", "1.2.3-01", "1.2.3-a.00", "1.2.3-a..b",
      "1.2.3+", "1.2.3+a..b", "1.2.3+a+b", "1.2.3-a_b", "1.2.3-é",
      " 1.2.3", "1.2.3 ", "1.2.3'"\\n\", \"1.2.3-alpha\\n\",
    ]) {
      assert.throws(() => compare(invalid, \"1.2.3\"), undefined, invalid);
      assert.throws(() => compare(\"1.2.3\", invalid), undefined, invalid);
    }
  });
}
EOF
